##############
def attr(self, *args, **kwargs):
    """Attributes manipulation
    """

    mapping = {'class_': 'class', 'for_': 'for'}

    attr = value = no_default
    length = len(args)
    if length == 1:
        attr = args[0]
        attr = mapping.get(attr, attr)
    elif length == 2:
        attr, value = args
        attr = mapping.get(attr, attr)
    elif kwargs:
        attr = {}
        for k, v in kwargs.items():
            attr[mapping.get(k, k)] = v
    else:
        raise ValueError('Invalid arguments %s %s' % (args, kwargs))

    if not self:
        return None
    elif isinstance(attr, dict):
        for tag in self:
            for key, value in attr.items():
                tag.set(key, value)
    elif value is no_default:
        return self[0].get(attr)
    elif value is None:
        return self.remove_attr(attr)
    else:
        for tag in self:
            tag.set(attr, value)
    return self

@with_camel_case_alias
def remove_attr(self, name):
    """Remove an attribute::

        >>> d = PyQuery('<div id="myid"></div>')
        >>> d.remove_attr('id')
        [<div>]
        >>> d.removeAttr('id')
        [<div>]

    ..
    """
    for tag in self:
        try:
            del tag.attrib[name]
        except KeyError:
            pass
    return self

