class TestConstruction(TestCase):

    def test_typeerror_on_invalid_value(self):
        self.assertRaises(TypeError, pq, object())

    def test_empty_markup_returns_empty_doc(self):
        for markup in ('', '   ', '\n', '\t  \n'):
            doc = pq(markup)
            self.assertEqual(len(doc), 0)
            self.assertEqual(list(doc), [])
            self.assertEqual(doc.html(), None)


class TestHTML4Compatibility(TestCase):
    """The tree shape must not depend on the libxml2 html parser flavour"""

    def test_unknown_entities_are_kept_as_text(self):
        doc = pq('<div>a three-headed HTML&dash;Entity!</div>')
        self.assertEqual(doc.text(), 'a three-headed HTML&dash;Entity!')
        self.assertIn('HTML&amp;dash;Entity!', doc.__html__())

    def test_html4_entities_are_resolved(self):
        self.assertEqual(pq('<div>&eacute;&nbsp;&lt;</div>').text(),
                         '\xe9\xa0<')

    def test_loose_text_is_wrapped_in_a_paragraph(self):
        doc = pq('REQUEST_METHOD: GET\nQUERY_STRING: q=foo\n')
        self.assertEqual(len(doc('p')), 1)
        self.assertIn('REQUEST_METHOD: GET', doc('p').text())

    def test_inline_wrapper_is_left_alone(self):
        self.assertEqual(pq('<span>youhou</span>').outer_html(),
                         '<span>youhou</span>')

    def test_textarea_content_is_parsed_as_markup(self):
        doc = pq('<textarea>Spam\n<b>Eggs</b>\nBacon</textarea>')
        self.assertEqual(doc('textarea').val(), 'Spam\n<b>Eggs</b>\nBacon')
        self.assertEqual(len(doc('textarea b')), 1)

    def test_textarea_text_is_left_alone(self):
        doc = pq('<textarea>a &lt; b</textarea>')
        self.assertEqual(doc('textarea').val(), 'a &lt; b')


